    box-shadow: 0 1px 2px rgba(0,0,0,0.12);
}

/* 回答：横线笔记本纸 + 红色边距线 + 蓝色 A 徽章 + REPLIED 印章 */
.xt-collapse-1 .xt-text-anonAnswer {
    position: relative;
    background-color: #fffdf8 !important;
    background-image:
        linear-gradient(to right, transparent 36px, rgba(230,110,110,0.55) 36px, rgba(230,110,110,0.55) 37px, transparent 37px),
        repeating-linear-gradient(to bottom, transparent 0, transparent 21px, #cfe0ee 21px, #cfe0ee 22px) !important;
