    margin: 0 16px 18px 22px !important;
    font-size: 12.5px !important;
    line-height: 22px !important;
    color: #1f3a5c !important;
    transform: rotate(1deg);
    box-shadow: 0 3px 6px rgba(0,0,0,0.14) !important;
}
.xt-collapse-1 .xt-text-anonAnswer::before {
    content: "A";
    display: block;
    position: absolute;
    left: 9px; top: 2px;
    width: 18px; height: 18px; line-height: 18px;
    text-align: center;
    border-radius: 50%;
    font-size: 11px; font-weight: bold;
    color: #fff;
    background: linear-gradient(to bottom, #7ec0ff, #2f7fd8);
    border: 1px solid #2467b3;
    box-shadow: 0 1px 2px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.5);
}
.xt-collapse-1 .xt-text-anonAnswer::after {
    content: "REPLIED";
    display: block;
    position: absolute;
